import{_ as e,a,o as d,a6 as o}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Catalog Products — Mass Update Status","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-product-mass-update-status","title":"Mass Update Catalog Product Status","description":"Bulk-flips the `status` flag of a batch of products to either 0 (disabled) or 1 (enabled). Mirrors Bagisto monolith `ProductController::massUpdate` — best-effort, fires `catalog.product.update.before` / `.after` for each ID.","query":"curl -X POST \\"https://your-domain.com/api/admin/catalog/products/mass-update-status\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\n    \\"indices\\": [12, 18],\\n    \\"value\\": 1\\n  }\'\\n","variables":"{\\n  \\"indices\\": [12, 18],\\n  \\"value\\": 1\\n}\\n","response":"{\\n  \\"id\\": 1,\\n  \\"updated\\": [12, 18],\\n  \\"message\\": \\"Products status updated successfully.\\"\\n}\\n","commonErrors":[{"error":"Bad Request (400)","cause":"Empty `indices`, or `value` not 0/1","solution":"Send a non-empty integer array and an integer 0 or 1"},{"error":"Forbidden (403)","cause":"Admin role lacks `catalog.products.edit`","solution":"Grant the permission to the admin role"}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/products/mass-update-status.md","filePath":"api/rest-api/admin/catalog/products/mass-update-status.md","lastUpdated":1787725411000}'),r={name:"api/rest-api/admin/catalog/products/mass-update-status.md"};function s(n,t,i,c,u,l){return d(),a("div",null,t[0]||(t[0]=[o('<h1 id="catalog-products-—-mass-update-status" tabindex="-1">Catalog Products — Mass Update Status <a class="header-anchor" href="#catalog-products-—-mass-update-status" aria-label="Permalink to &quot;Catalog Products — Mass Update Status&quot;">​</a></h1><p>Bulk-flips status across a batch of catalog products. Each ID fires the same core event hooks the single-product update does (<code>catalog.product.update.before</code> / <code>.after</code>), so search reindex, cache flush etc. still trigger.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/products/mass-update-status</code></td><td>POST</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request body&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>indices</code></td><td>int[]</td><td>yes</td><td>Non-empty array of product IDs.</td></tr><tr><td><code>value</code></td><td>integer</td><td>yes</td><td><code>0</code> (disabled) or <code>1</code> (enabled).</td></tr></tbody></table><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>200 OK</code></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Always <code>1</code>. This is an action result, not a record — ignore it.</td></tr><tr><td><code>updated</code></td><td>int[]</td><td>The ids the call attempted to update.</td></tr><tr><td><code>message</code></td><td>string</td><td>Translated confirmation.</td></tr></tbody></table><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><p>Each id fires the same events as a single-product update, so search reindexing and cache flushing still run per product. That makes a large batch meaningfully slower than the row count suggests.</p><p>The status flip is the only change — nothing else on the product is touched, and there is no partial-failure report beyond the returned <code>updated</code> list.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP</th><th>Detail</th></tr></thead><tbody><tr><td><code>400</code></td><td><code>The indices field is required and must be a non-empty array.</code></td></tr><tr><td><code>400</code></td><td><code>The value field is required and must be 0 or 1.</code></td></tr><tr><td><code>401</code></td><td><code>Unauthenticated.</code></td></tr><tr><td><code>403</code></td><td><code>You do not have permission to manage products.</code> — token lacks <code>catalog.products.edit</code></td></tr></tbody></table><p>Note the validation failures here are <code>400</code>, not the <code>422</code> used by the single-product create and update endpoints.</p>',15)]))}const m=e(r,[["render",s]]);export{p as __pageData,m as default};
